  "segments": [
    {
      "startSecond": 0.0,
      "endSecond": 4.6,
      "speech": "Bây giờ là 5:30 sáng, trời hôm nay mùa hè nên là sáng rất là sớm."
    },
    {
      "startSecond": 4.6,
      "endSecond": 7.4,
      "speech": "Chúng ta bắt đầu ngày mới bằng một viên kẽm ở đây nhá."
    },
    {
      "startSecond": 7.4,
      "endSecond": 9.9,
      "speech": "Tại sao lại phải uống kẽm trước ăn sáng?"
    },
    {
      "startSecond": 10.3,
      "endSecond": 13.5,
      "speech": "Thì để chúng ta có thể hấp thu vi chất của kẽm tốt hơn."
    },
    {
      "startSecond": 13.5,
      "endSecond": 17.1,
      "speech": "Bác sĩ Biên thì thường uống khoảng trước 30 phút một viên bé tí này thôi."
    },
    {
      "startSecond": 17.1,
      "endSecond": 20.3,
      "speech": "Nhiều người mà gặp phải tình trạng là hay nhiệt miệng này,"
    },
    {
      "startSecond": 20.3,
      "endSecond": 21.6,
      "speech": "hay mụn nội tiết,"
    },
    {
      "startSecond": 21.6,
      "endSecond": 24.3,
      "speech": "cứ nghĩ là do nóng trong, nhưng mà hãy thử bổ sung kẽm."
    },
    {
      "startSecond": 24.3,
      "endSecond": 26.6,
      "speech": "Cái loại viên kẽm này có bổ sung thêm vitamin C,"
    },
    {
      "startSecond": 26.6,
      "endSecond": 29.8,
      "speech": "xem cái tình trạng mụn rồi cái tình trạng nhiệt miệng nó có cải thiện không nha."
    },
    {
      "startSecond": 29.8,
      "endSecond": 32.2,
      "speech": "Trước khi ăn 30 phút thì làm viên kẽm đã."
    },
    {
      "startSecond": 33.7,
      "endSecond": 37.6,
      "speech": "Loại kẽm bác sĩ Biên đang dùng là kẽm Pino nhập khẩu từ Anh."
    },
    {
      "startSecond": 37.6,
      "endSecond": 43.1,
      "speech": "Đấy, nó là kẽm citrate, kẽm hữu cơ, nên là chúng ta có thể uống lúc bụng đói được, không vấn đề gì cả."
    },
    {
      "startSecond": 43.1,
      "endSecond": 48.1,
      "speech": "Với những ai mà uống xong có cảm giác tình trạng là nôn nao sau khi uống thì chúng ta uống sau bữa ăn."
    }
  ],
  "onScreenText": [
    {
      "startSecond": 0.0,
      "endSecond": 4.5,
      "text": "5:30 AM"
    },
    {
      "startSecond": 7.4,
      "endSecond": 9.9,
      "text": "TẠI SAO PHẢI UỐNG KẼM TRƯỚC ĂN SÁNG"
    },
    {
      "startSecond": 10.3,
      "endSecond": 12.3,
      "text": "THÌ ĐỂ CHÚNG TA CÓ THỂ"
    },
    {
      "startSecond": 12.3,
      "endSecond": 13.5,
      "text": "HẤP THỤ VI CHẤT CỦA KẼM TỐT HƠN."
    },
    {
      "startSecond": 14.1,
      "endSecond": 15.6,
      "text": "BÁC SĨ BIÊN THÌ THƯỜNG UỐNG"
    },
    {
      "startSecond": 15.6,
      "endSecond": 17.1,
      "text": "KHOẢNG TRƯỚC 30 PHÚT MỘT VIÊN BÉ TÍ NÀY THÔI."
    },
    {
      "startSecond": 17.1,
      "endSecond": 18.9,
      "text": "NHIỀU NGƯỜI MÀ GẶP PHẢI TÌNH TRẠNG"
    },
    {
      "startSecond": 18.9,
      "endSecond": 19.9,
      "text": "LÀ HAY NHIỆT MIỆNG NÀY"
    },
    {
      "startSecond": 19.9,
      "endSecond": 21.0,
      "text": "HAY MỤN NỘI TIẾT"
    },
    {
      "startSecond": 21.0,
      "endSecond": 22.8,
      "text": "CỨ NGHĨ LÀ DO NÓNG TRONG"
    },
    {
      "startSecond": 22.8,
      "endSecond": 24.1,
      "text": "NHƯNG MÀ HÃY THỬ BỔ SUNG KẼM"
    },
    {
      "startSecond": 24.1,
      "endSecond": 25.4,
      "text": "LOẠI VIÊN KẼM NÀY"
    },
    {
      "startSecond": 25.4,
      "endSecond": 26.5,
      "text": "CÓ BỔ SUNG THÊM VITAMIN C"
    },
    {
      "startSecond": 25.5,
      "endSecond": 26.6,
      "text": "VITAMIN C"
    },
    {
      "startSecond": 26.5,
      "endSecond": 27.8,
      "text": "XEM CÁI TÌNH TRẠNG MỤN"
    },
    {
      "startSecond": 27.8,
      "endSecond": 29.0,
      "text": "RỒI CÁI TÌNH TRẠNG NHIỆT MIỆNG"
    },
    {
      "startSecond": 29.0,
      "endSecond": 29.8,
      "text": "NÓ CÓ CẢI THIỆN KHÔNG NHA"
    },
    {
      "startSecond": 29.8,
      "endSecond": 32.2,
      "text": "TRƯỚC KHI ĂN 30 PHÚT THÌ LÀM VIÊN KẼM ĐÃ."
    },
    {
      "startSecond": 32.2,
      "endSecond": 34.2,
      "text": "PLAY"
    },
    {
      "startSecond": 34.2,
      "endSecond": 36.3,
      "text": "LOẠI KẼM BÁC SĨ BIÊN ĐANG DÙNG LÀ KẼM PINO"
    },
    {
      "startSecond": 36.3,
      "endSecond": 37.6,
      "text": "NHẬP KHẨU TỪ ANH"
    },
    {
      "startSecond": 37.6,
      "endSecond": 39.7,
      "text": "NÓ LÀ KẼM CITRATE KẼM HỮU CƠ"
    },
    {
      "startSecond": 39.7,
      "endSecond": 41.9,
      "text": "NÊN LÀ CHÚNG TA CÓ THỂ UỐNG LÚC BỤNG ĐÓI ĐƯỢC"
    },
    {
      "startSecond": 41.9,
      "endSecond": 43.1,
      "text": "KHÔNG VẤN ĐỀ GÌ CẢ."
    },
    {
      "startSecond": 43.1,
      "endSecond": 44.5,
      "text": "VỚI NHỮNG AI MÀ UỐNG XONG"
    },
    {
      "startSecond": 44.5,
      "endSecond": 46.1,
      "text": "CÓ CẢM GIÁC TÌNH TRẠNG LÀ NÔN NAO"
    },
    {
      "startSecond": 46.1,
      "endSecond": 47.0,
      "text": "SAU KHI UỐNG"
    },
    {
      "startSecond": 47.0,
      "endSecond": 48.1,
      "text": "THÌ CHÚNG TA UỐNG SAU BỮA ĂN."
    }
  ]
}
